// Auto-clear delay in ms — exported so tests can reference the same constant
export const TOAST_DELAY = 4000

export function useToast() {
  const [message, setMessage] = useState(null)
  // ref holds the active timer id so we can cancel it on each new call
  const timerRef = useRef(null)

  const clear = useCallback(() => {
    setMessage(null)
    if (timerRef.current) {
      clearTimeout(timerRef.current)
      timerRef.current = null
    }
  }, [])

  const toast = useCallback((msg) => {
    // cancel any existing auto-clear timer before starting a new one
    if (timerRef.current) {
      clearTimeout(timerRef.current)
    }
    setMessage(msg)
    timerRef.current = setTimeout(() => {
      setMessage(null)
      timerRef.current = null
    }, TOAST_DELAY)
  }, [])

  return { toast, message, clear }
}
