import { useToast } from '../hooks/useToast'
import Toast from '../components/Toast'

const ToastContext = createContext(null)

export function ToastProvider({ children }) {
  const { toast, message, clear } = useToast()

  return (
    <ToastContext.Provider value={{ toast, message, clear }}>
      {children}
      {/* Single Toast instance mounted here so it overlays all routes */}
      <Toast message={message} onDismiss={clear} />
    </ToastContext.Provider>
  )
}

// Hook for consumers — throws if used outside ToastProvider
export function useToastContext() {
  const ctx = useContext(ToastContext)
  if (!ctx) throw new Error('useToastContext must be used within a ToastProvider')
  return ctx
}
