    "content": "import { renderHook, act } from '@testing-library/react'
import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest'
import { useToast, TOAST_DELAY } from './useToast'

describe('useToast', () => {
  beforeEach(() => {
    vi.useFakeTimers()
  })

  afterEach(() => {
    vi.useRealTimers()
  })

  it('message appears after toast() is called', () => {
    const { result } = renderHook(() => useToast())

    act(() => {
      result.current.toast('Hello world')
    })

    expect(result.current.message).toBe('Hello world')
  })

  it('message auto-clears after 4000ms', () => {
    const { result } = renderHook(() => useToast())

    act(() => {
      result.current.toast('Auto clear me')
    })

    expect(result.current.message).toBe('Auto clear me')

    // advance time just before the delay — message should still be present
    act(() => {
      vi.advanceTimersByTime(TOAST_DELAY - 1)
    })
    expect(result.current.message).toBe('Auto clear me')

    // advance past the delay — message should be gone
    act(() => {
      vi.advanceTimersByTime(1)
    })
    expect(result.current.message).toBeNull()
  })

  it('dismiss clears the message immediately', () => {
    const { result } = renderHook(() => useToast())

    act(() => {
      result.current.toast('Dismiss me')
    })
    expect(result.current.message).toBe('Dismiss me')

    act(() => {
      result.current.clear()
    })
    expect(result.current.message).toBeNull()
  })

  it('calling toast() twice resets the timer so only one auto-clear fires', () => {
    const { result } = renderHook(() => useToast())

    act(() => {
      result.current.toast('First message')
    })

    // advance halfway through the first timer
    act(() => {
      vi.advanceTimersByTime(TOAST_DELAY / 2)
    })

    // second call should reset the timer
    act(() => {
      result.current.toast('Second message')
    })
    expect(result.current.message).toBe('Second message')

    // advance to where the first timer would have fired — message must still be present
    act(() => {
      vi.advanceTimersByTime(TOAST_DELAY / 2)
    })
    expect(result.current.message).toBe('Second message')

    // advance the remaining time for the second timer
    act(() => {
      vi.advanceTimersByTime(TOAST_DELAY / 2)
    })
    expect(result.current.message).toBeNull()
  })
})
